<?php $draft=$cycle['status']==='draft'; ?>
<div class="page-heading admin-heading"><div><a class="back-link" href="<?= url('admin/admissions') ?>">← Admission cycles</a><span class="eyebrow"><?= e($cycle['code']) ?> · version <?= e($cycle['configuration_version']) ?></span><h1><?= e($cycle['name']) ?></h1><p>Stored state: <?= e($cycle['status']) ?> · Effective state: <?= e(str_replace('_',' ',$cycle['effective_status'])) ?> · <?= e($cycle['session_name']) ?></p></div><div class="heading-actions"><a class="button button-outline" target="_blank" href="<?= url('admin/admissions/'.$cycle['id'].'/preview') ?>">Preview ↗</a><?php if($draft&&can('admissions.publish')):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/publish') ?>"><?= csrf_field() ?><button class="button button-primary" data-confirm="Publish this cycle and create an immutable configuration version?" <?= !$readiness['ready']?'disabled':'' ?>>Publish cycle</button></form><?php elseif(in_array($cycle['status'],['published','open'],true)&&can('admissions.manage')):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/close') ?>"><?= csrf_field() ?><button class="button button-outline" data-confirm="Close this cycle to new applications?">Close cycle</button></form><?php elseif($cycle['status']==='closed'&&can('admissions.manage')):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/archive') ?>"><?= csrf_field() ?><button class="button button-outline" data-confirm="Archive this closed cycle?">Archive</button></form><?php endif?></div></div>
<div class="admin-stat-grid"><article><div class="stat-icon teal">▤</div><div><span>Applications</span><b><?= number_format($stats['applications']) ?></b><small><?= number_format($stats['submitted']) ?> submitted</small></div></article><article><div class="stat-icon green">✓</div><div><span>Admitted</span><b><?= number_format($stats['admitted']) ?></b><small>Confirmed records</small></div></article><article><div class="stat-icon gold">◎</div><div><span>Programmes</span><b><?= count($programs) ?></b><small>Assigned to cycle</small></div></article><article><div class="stat-icon <?= $readiness['ready']?'green':'red' ?>">!</div><div><span>Publish readiness</span><b><?= $readiness['ready']?'Ready':count($readiness['errors']).' issues' ?></b><small><?= count($readiness['warnings']) ?> warnings</small></div></article></div>
<section class="card" id="readiness"><div class="card-heading"><div><span class="eyebrow">Publication gate</span><h2>Readiness validation</h2></div><span class="status-pill status-<?= $readiness['ready']?'verified':'rejected' ?>"><?= $readiness['ready']?'Ready to publish':'Action required' ?></span></div><?php if(!$readiness['errors']&&!$readiness['warnings']):?><p>Dates, programmes, seats, eligibility, forms, documents and fees passed validation.</p><?php endif?><?php foreach($readiness['errors'] as $error):?><div class="alert alert-warning"><?= e($error) ?></div><?php endforeach?><?php foreach($readiness['warnings'] as $warning):?><div class="report-notice"><span>i</span><p><?= e($warning) ?></p></div><?php endforeach?></section>
<section class="card settings-panel" id="cycle-settings"><div class="card-heading"><div><span class="eyebrow">Cycle details</span><h2>Identity, dates and applicant copy</h2></div><span class="status-pill status-<?= e($cycle['status']) ?>"><?= e(ucfirst($cycle['status'])) ?></span></div><?php if($draft):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id']) ?>" enctype="multipart/form-data"><?= csrf_field() ?><div class="form-grid three"><label><span>Academic session</span><select name="academic_session_id" required><?php foreach($sessions as $session):?><option value="<?= e($session['id']) ?>"<?= selected($cycle['academic_session_id'],$session['id']) ?>><?= e($session['name']) ?></option><?php endforeach?></select></label><label><span>Name</span><input name="name" value="<?= e($cycle['name']) ?>" required></label><label><span>Code</span><input name="code" value="<?= e($cycle['code']) ?>" required></label><label><span>Public slug</span><input name="slug" value="<?= e($cycle['slug']) ?>" required></label><label><span>Opening</span><input type="datetime-local" name="starts_at" value="<?= e(date('Y-m-d\TH:i',strtotime($cycle['starts_at']))) ?>" required></label><label><span>Closing</span><input type="datetime-local" name="ends_at" value="<?= e(date('Y-m-d\TH:i',strtotime($cycle['ends_at']))) ?>" required></label><label><span>Correction deadline</span><input type="datetime-local" name="correction_deadline" value="<?= $cycle['correction_deadline']?e(date('Y-m-d\TH:i',strtotime($cycle['correction_deadline']))):'' ?>"></label><label><span>Number prefix</span><input name="application_number_prefix" value="<?= e($cycle['application_number_prefix']) ?>" required></label><label><span>Maximum preferences</span><input type="number" min="1" max="10" name="max_program_preferences" value="<?= e($cycle['max_program_preferences']) ?>"></label><label><span>Closing-soon hours</span><input type="number" min="0" max="720" name="closing_soon_hours" value="<?= e($cycle['closing_soon_hours']) ?>"></label><label class="full"><span>Public summary</span><textarea name="summary" rows="2"><?= e($cycle['summary']) ?></textarea></label><label class="full"><span>Instructions</span><textarea name="instructions" rows="4"><?= e($cycle['instructions']) ?></textarea></label><label class="full"><span>Declaration</span><textarea name="declaration_text" rows="3"><?= e($cycle['declaration_text']) ?></textarea></label><label class="full"><span>Prospectus PDF (maximum 10 MB)</span><input type="file" name="prospectus" accept="application/pdf"><small><?= $cycle['prospectus_original_name']?'Current: '.e($cycle['prospectus_original_name']):'No prospectus uploaded' ?></small></label></div><button class="button button-primary">Save cycle settings</button></form><?php else:?><p>Published configuration is immutable. Existing applications continue to use version <?= e($cycle['configuration_version']) ?>. Duplicate this cycle to create an editable draft.</p><?php endif?></section>
<section class="card" id="programmes"><div class="card-heading"><div><span class="eyebrow">Programmes, seats, eligibility & fees</span><h2>Cycle programmes</h2></div></div><?php if(!$programs):?><div class="empty-inline">No programme assigned.</div><?php endif?><?php foreach($programs as $program):?><details class="config-accordion" open><summary><div><b><?= e($program['name']) ?></b><small><?= e($program['code']) ?> · <?= number_format((int)$program['seat_capacity']) ?> seats · <?= number_format((int)$program['applicants']) ?> applicants</small></div><span class="status-pill status-<?= e($program['status']) ?>"><?= e($program['status']) ?></span></summary><div class="settings-stack"><section id="seats"><h3>Seat matrix</h3><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/seats') ?>"><?= csrf_field() ?><div class="form-grid three"><?php foreach($program['seats'] as $seat):?><label><span><?= e($seat['category'].' · '.$seat['quota']) ?> (<?= e($seat['filled_seats']) ?> allocated)</span><input type="number" min="<?= e($seat['filled_seats']) ?>" name="seats[<?= e($seat['id']) ?>]" value="<?= e($seat['seats']) ?>" <?= !$draft?'disabled':'' ?>></label><?php endforeach?><?php if($draft):?><label><span>New category</span><select name="new_category"><option value="">No new row</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>New quota</span><input name="new_quota" value="state"></label><label><span>New seats</span><input type="number" min="0" name="new_seats" value="0"></label><?php endif?></div><?php if($draft):?><p class="form-hint">All category rows, including a new row, must total exactly <?= number_format((int)$program['seat_capacity']) ?>.</p><button class="button button-outline">Save seat matrix</button><?php endif?></form></section><section id="eligibility"><h3>Eligibility rules</h3><div class="table-wrap"><table><thead><tr><th>Field</th><th>Operator</th><th>Expected</th><th>Blocking</th><th>Message</th></tr></thead><tbody><?php foreach($program['eligibility'] as $rule):?><tr><td><?= e($rule['field_name']) ?></td><td><code><?= e($rule['operator']) ?></code></td><td><?= e($rule['comparison_value']) ?></td><td><?= $rule['is_blocking']?'Yes':'Review' ?></td><td><?= e($rule['message']) ?></td></tr><?php endforeach?></tbody></table></div><?php if($draft):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/eligibility') ?>" class="form-grid three"><?= csrf_field() ?><label><span>Rule type</span><select name="rule_type"><option>marks</option><option>subject</option><option>age</option><option>category</option><option>entrance</option><option>custom</option></select></label><label><span>Field key</span><input name="field_name" required placeholder="class_12_percentage"></label><label><span>Operator</span><select name="operator"><?php foreach(['eq','neq','gt','gte','lt','lte','in','not_in','contains','between','regex'] as $operator):?><option><?= e($operator) ?></option><?php endforeach?></select></label><label><span>Comparison value</span><input name="comparison_value" required></label><label class="span-2"><span>Applicant/reviewer message</span><input name="message" required></label><label class="check-control"><input type="checkbox" name="is_blocking" value="1"><span>Blocking rule</span></label><button class="button button-outline">Add rule</button></form><?php endif?></section><section id="fees"><h3>Fee rules</h3><div class="table-wrap"><table><thead><tr><th>Type</th><th>Category</th><th>Amount</th><th>Due</th><th>Late fee</th></tr></thead><tbody><?php foreach($program['fees'] as $fee):?><tr><td><?= e(str_replace('_',' ',$fee['fee_type'])) ?></td><td><?= e($fee['category_code']?:'All') ?></td><td><?= money($fee['amount']) ?></td><td><?= format_date($fee['due_at'],true) ?></td><td><?= money($fee['late_fee_amount']) ?></td></tr><?php endforeach?></tbody></table></div><?php if($draft):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/fees') ?>" class="form-grid three"><?= csrf_field() ?><label><span>Fee type</span><select name="fee_type"><option value="application_fee">Application fee</option><option value="admission_fee">Admission fee</option></select></label><label><span>Category</span><select name="category_code"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Label</span><input name="label" required></label><label><span>Amount</span><input type="number" min="0" step=".01" name="amount" required></label><label><span>Due date</span><input type="datetime-local" name="due_at"></label><label><span>Late fee</span><input type="number" min="0" step=".01" name="late_fee_amount" value="0"></label><label class="full"><span>Refund policy</span><textarea name="refund_policy"></textarea></label><button class="button button-outline">Add fee rule</button></form><?php endif?></section></div></details><?php endforeach?><?php if($draft&&$availablePrograms):?><form class="settings-inline-form" method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs') ?>"><?= csrf_field() ?><h3>Add programme</h3><div class="form-grid three"><label><span>Programme</span><select name="program_id" required><?php foreach($availablePrograms as $program):?><option value="<?= e($program['id']) ?>"><?= e($program['name']) ?></option><?php endforeach?></select></label><label><span>Seat capacity</span><input type="number" min="1" name="seat_capacity" required></label><label><span>Application fee</span><input type="number" min="0" step=".01" name="application_fee" value="0"></label><label><span>Admission fee</span><input type="number" min="0" step=".01" name="admission_fee" value="0"></label><label><span>General minimum marks</span><input type="number" min="0" max="100" step=".01" name="minimum_marks_general"></label><label><span>Reserved minimum marks</span><input type="number" min="0" max="100" step=".01" name="minimum_marks_reserved"></label><label><span>Minimum age</span><input type="number" min="0" name="min_age"></label><label><span>Maximum age</span><input type="number" min="0" name="max_age"></label><label><span>Accepted entrance exams</span><input name="accepted_entrance_exams"></label></div><button class="button button-primary">Add programme</button></form><?php endif?></section>
<section class="card" id="form-builder"><div class="card-heading"><div><span class="eyebrow">Dynamic application</span><h2>Form builder</h2></div><span><?= count($sections) ?> sections · <?= count($fields) ?> fields</span></div><div class="table-wrap"><table><thead><tr><th>Section</th><th>Key</th><th>Field</th><th>Type</th><th>Binding</th><th>Required</th><th>Status</th></tr></thead><tbody><?php foreach($sections as $section): $sectionFields=array_filter($fields,fn($field)=>(int)$field['section_id']===(int)$section['id']); if(!$sectionFields):?><tr><td><b><?= e($section['title']) ?></b></td><td><code><?= e($section['section_key']) ?></code></td><td colspan="5">No fields</td></tr><?php endif; foreach($sectionFields as $field):?><tr><td><b><?= e($section['title']) ?></b></td><td><code><?= e($field['field_key']) ?></code></td><td><?= e($field['label']) ?></td><td><?= e($field['field_type']) ?></td><td><?= e($field['canonical_binding']?:'Custom response') ?></td><td><?= $field['is_required']?'Yes':'No' ?></td><td><?= e($field['status']) ?></td></tr><?php endforeach; endforeach?></tbody></table></div><?php if($draft):?><div class="admin-dashboard-grid lower"><form class="settings-inline-form" method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-sections') ?>"><?= csrf_field() ?><h3>Add form section</h3><label><span>Section key</span><input name="section_key" required></label><label><span>Title</span><input name="title" required></label><label><span>Description</span><input name="description"></label><label><span>Sort order</span><input type="number" name="sort_order" value="100"></label><button class="button button-outline">Add section</button></form><form class="settings-inline-form" method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-fields') ?>"><?= csrf_field() ?><h3>Add form field</h3><div class="form-grid"><label><span>Section</span><select name="section_id" required><?php foreach($sections as $section):?><option value="<?= e($section['id']) ?>"><?= e($section['title']) ?></option><?php endforeach?></select></label><label><span>Field key</span><input name="field_key" required></label><label><span>Label</span><input name="label" required></label><label><span>Type</span><select name="field_type"><?php foreach(['text','textarea','email','tel','number','date','select','radio','checkbox','multiselect','file'] as $type):?><option><?= e($type) ?></option><?php endforeach?></select></label><label><span>Canonical binding (optional)</span><input name="canonical_binding" placeholder="applicant_profiles.field"></label><label><span>Placeholder</span><input name="placeholder"></label><label class="full"><span>Options, one per line as value|Label</span><textarea name="options"></textarea></label><label class="full"><span>Help text</span><input name="help_text"></label><label class="full"><span>Conditional rule JSON (optional)</span><textarea name="conditional_rules" placeholder='{"field":"category","operator":"eq","value":"SC"}'></textarea></label><label class="check-control"><input type="checkbox" name="is_required" value="1"><span>Required</span></label><label class="check-control"><input type="checkbox" name="is_searchable" value="1"><span>Searchable</span></label></div><button class="button button-outline">Add field</button></form></div><?php endif?></section>
<section class="card" id="documents"><div class="card-heading"><div><span class="eyebrow">Protected uploads</span><h2>Document requirements</h2></div></div><div class="table-wrap"><table><thead><tr><th>Document</th><th>Programme</th><th>Category</th><th>Stage</th><th>Required</th></tr></thead><tbody><?php foreach($requirements as $requirement):?><tr><td><b><?= e($requirement['name']) ?></b><small class="cell-subtitle"><?= e($requirement['code']) ?></small></td><td><?= e($requirement['program_name']?:'All') ?></td><td><?= e($requirement['category']?:'All') ?></td><td><?= e($requirement['stage']) ?></td><td><?= $requirement['is_required']?'Yes':'No' ?></td></tr><?php endforeach?></tbody></table></div><?php if($draft):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/documents') ?>" class="form-grid three"><?= csrf_field() ?><label><span>Document type</span><select name="document_type_id" required><?php foreach($documentTypes as $type):?><option value="<?= e($type['id']) ?>"><?= e($type['name']) ?></option><?php endforeach?></select></label><label><span>Programme scope</span><select name="program_id"><option value="">All programmes</option><?php foreach($programs as $program):?><option value="<?= e($program['program_id']) ?>"><?= e($program['name']) ?></option><?php endforeach?></select></label><label><span>Category scope</span><select name="category"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Stage</span><select name="stage"><option>application</option><option>admission</option></select></label><label><span>Sort order</span><input type="number" name="sort_order" value="100"></label><label class="check-control"><input type="checkbox" name="is_required" value="1"><span>Required</span></label><button class="button button-outline">Save requirement</button></form><?php endif?></section>
<section class="card"><div class="card-heading"><div><span class="eyebrow">Immutable history</span><h2>Configuration versions</h2></div></div><?php if(!$versions):?><p>No published version yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Version</th><th>Status</th><th>Hash</th><th>Published by</th><th>Time</th></tr></thead><tbody><?php foreach($versions as $version):?><tr><td><b>v<?= e($version['version_no']) ?></b></td><td><?= e($version['status']) ?></td><td><code><?= e(substr($version['snapshot_hash'],0,16)) ?>…</code></td><td><?= e($version['creator_name']?:'System migration') ?></td><td><?= format_date($version['created_at'],true) ?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
